package local.lito381.server;
import java.util.*;
/** Exact frozen Source interval oracle, immutable factory metadata and actual detached NPC schedules. */
public final class SourceNpcActionIntervalsPlan {
 static int cases;static void check(boolean b,String why){if(!b)throw new AssertionError(why);cases++;}static void set(Object o,String k,Object v)throws Exception{SourceSignedRecoveryPlan.set(o,k,v);}
 static Object definition(String name)throws Exception{var type=Class.forName("local.lito381.server.BattleTimeAttackMagicSkillCatalog$"+name);var parts=type.getRecordComponents();var types=Arrays.stream(parts).map(java.lang.reflect.RecordComponent::getType).toArray(Class<?>[]::new);var values=new Object[parts.length];for(int i=0;i<parts.length;i++){String n=parts[i].getName();if(parts[i].getType()==int.class)values[i]=switch(n){case"npcId","summonNpcId","effectNpcId"->123;case"actNo","actionId","sourceActionId","effectGfx","baseDamage","diceCount","dieSides","summonMinimum","summonRandomBound"->1;case"triggerChance"->100;case"triggerRange","maximumRange"->10;case"leverage"->10;case"skillId"->4;case"actionDelayMillis"->10;case"mpCost"->5;case"reuseDelayMillis"->50;case"triggerCount","attribute"->2;case"durationMillis"->name.equals("VisualDefinition")?0:100;case"pulseIntervalMillis"->10;case"pulseCount"->10;case"fixedDamage"->1;default->0;};else if(parts[i].getType().isEnum())values[i]=parts[i].getType().getEnumConstants()[0];else values[i]="detached";}var ctor=type.getDeclaredConstructor(types);ctor.setAccessible(true);return ctor.newInstance(values);}
 static void schedule(Object actor,Object def,String name,long now)throws Exception{try{var m=actor.getClass().getDeclaredMethod(name,long.class,def.getClass());m.setAccessible(true);m.invoke(actor,now,def);}catch(java.lang.reflect.InvocationTargetException failure){throw new Exception("actual original schedule "+name,failure.getCause());}}
 static int normalSchedules(SourceNpcActionIntervalOracle oracle,NativeSourceNpcFactoryType.Stamp ordinary,NativeSourceNpcFactoryType.Stamp qualified,NativeSourceNpcFactoryType.Stamp prior)throws Exception{
  var catalog=BattleAnimationCatalog.get();var sprites=(Map<Integer,Map<Integer,BattleAnimationCatalog.Animation>>)CombatAccess.field(catalog,"sprites");int gfx=sprites.entrySet().stream().filter(e->e.getKey()>0&&catalog.supportsTimedAction(e.getKey(),0)&&catalog.supportsTimedAction(e.getKey(),1)).mapToInt(Map.Entry::getKey).sorted().findFirst().orElseThrow();int count=0;long now=1000000;
  for(boolean timed:new boolean[]{false,true})for(var stamp:List.of(ordinary,qualified,prior))for(boolean haste:new boolean[]{false,true})for(boolean slow:new boolean[]{false,true})for(boolean wind:new boolean[]{false,true})for(int action:new int[]{0,1}){
   var actor=SourceNpcTargetFailurePlan.actor(timed,timed?889:888,stamp);if(timed)set(actor,"gfx",gfx);else{var type=Class.forName("local.lito381.server.BattleQuestEncounter$Template");var ctor=type.getDeclaredConstructor(int.class,int.class,String.class,int.class,int.class,int.class,int.class);ctor.setAccessible(true);set(actor,"template",ctor.newInstance(123,gfx,"detached",1,100,100,1));}
   set(actor,"mp",100);set(actor,"hasteExpiresAtNanos",haste?now+1000000000L:0L);set(actor,"slowExpiresAtNanos",slow?now+1000000000L:0L);set(actor,"windShackleExpiresAtNanos",wind?now+1000000000L:0L);
   var method=actor.getClass().getDeclaredMethod("schedule",long.class,int.class);method.setAccessible(true);method.invoke(actor,now,action);int base=Math.toIntExact(catalog.requireTimedAction(gfx,action).durationMillis());int millis=stamp.nativeSourceNpcBraveSpeed==null?BattleActionInterval.npcMillis(gfx,action,haste,slow,wind):oracle.calculate(base,action,haste,slow,stamp.nativeSourceNpcBraveSpeed,wind);
   if((long)CombatAccess.field(actor,"nextActionNanos")!=now+millis*1000000L||(int)CombatAccess.field(actor,"mp")!=100)throw new AssertionError("actual original normal schedule "+timed+"/"+action+"/"+stamp.nativeSourceNpcBraveSpeed+"/"+haste+"/"+slow+"/"+wind);count++;
  }return count;
 }
 public static void main(String[]args)throws Exception{
  var oracle=new SourceNpcActionIntervalOracle();int compared=0;for(int base:new int[]{Integer.MIN_VALUE,-1,0,1,2,3,10,39,40,41,101,960,65535,1000000,Integer.MAX_VALUE})for(int action:new int[]{-1,0,1,2,7})for(boolean haste:new boolean[]{false,true})for(boolean slow:new boolean[]{false,true})for(boolean brave:new boolean[]{false,true})for(boolean wind:new boolean[]{false,true}){int expected=oracle.calculate(base,action,haste,slow,brave,wind);int actual=NativeSourceNpcActionIntervals.calculate(base,action,haste,slow,brave,wind);if(actual!=expected)throw new AssertionError("exact Source NPC interval "+base+"/"+action+"/"+haste+"/"+slow+"/"+brave+"/"+wind+"="+actual+" expected "+expected);compared++;}check(compared==1200,"1200 exact frozen Source calculator plus NPC default interval comparisons");
  var legacy=new NativeSourceNpcFactoryType.Stamp("detached",123,"L1Monster",1,0);var prior=new NativeSourceNpcFactoryType.Stamp("detached",123,"L1Monster",1,0,false,true);var qualified=new NativeSourceNpcFactoryType.Stamp("detached",123,"L1Monster",1,0,false,true,true);var ordinary=new NativeSourceNpcFactoryType.Stamp("detached",123,"L1Monster",1,0,false,true,false);check(legacy.nativeSourceNpcBraveSpeed==null&&prior.nativeSourceNpcBraveSpeed==null,"old constructors remain unqualified and preserve complete original speed policy");check(Boolean.TRUE.equals(qualified.nativeSourceNpcBraveSpeed)&&Boolean.FALSE.equals(ordinary.nativeSourceNpcBraveSpeed),"new constructor freezes qualified true and false separately");check(qualified.equals(prior)&&qualified.hashCode()==prior.hashCode()&&qualified.getClass().getRecordComponents().length==5,"original record identity/components unaffected by static brave metadata");check(java.lang.reflect.Modifier.isFinal(qualified.getClass().getDeclaredField("nativeSourceNpcBraveSpeed").getModifiers()),"one immutable boxed scalar marker");
  var row=SourceCubeTemplatePlan.row(123);row.setImpl("L1Monster");row.set_bravespeed(true);var table=SourceCubeTemplatePlan.snapshot(Map.of(123,row),false);var born=NativeSourceNpcFactoryType.row(table,123);check(Boolean.TRUE.equals(born.nativeSourceNpcBraveSpeed),"actual original loaded-template birth port freezes Source brave");row.set_bravespeed(false);check(Boolean.TRUE.equals(born.nativeSourceNpcBraveSpeed)&&Boolean.FALSE.equals(NativeSourceNpcFactoryType.row(table,123).nativeSourceNpcBraveSpeed),"reload/template mutation affects new birth, never old actor metadata");
  long now=1000000;int schedules=0;for(boolean timed:new boolean[]{false,true})for(boolean isBrave:new boolean[]{false,true})for(boolean haste:new boolean[]{false,true})for(boolean slow:new boolean[]{false,true})for(boolean wind:new boolean[]{false,true}){var actor=SourceNpcTargetFailurePlan.actor(timed,timed?889:888,isBrave?qualified:ordinary);set(actor,"mp",100);set(actor,"skillReadyNanos",new HashMap<Integer,Long>());set(actor,"skillUseCounts",new HashMap<Integer,Integer>());set(actor,"hasteExpiresAtNanos",haste?now+1000000000L:0L);set(actor,"slowExpiresAtNanos",slow?now+1000000000L:0L);set(actor,"windShackleExpiresAtNanos",wind?now+1000000000L:0L);var snapshot=SourceNpcFactoryMemoryPlan.snapshot(actor);if(NativeSourceNpcFactoryMemory.proof(snapshot)!= (isBrave?qualified:ordinary))throw new AssertionError("original snapshot loses immutable brave birth");for(String kind:timed?List.of("Definition","SummonDefinition","GroundDefinition","VisualDefinition"):List.of("Definition","SummonDefinition")){set(actor,"mp",100);set(actor,"skillReadyNanos",new HashMap<Integer,Long>());set(actor,"skillUseCounts",new HashMap<Integer,Integer>());Object def=definition(kind);String method=switch(kind){case"Definition"->"scheduleMagic";case"SummonDefinition"->"scheduleSummon";case"GroundDefinition"->"scheduleGround";default->"scheduleVisual";};schedule(actor,def,method,now);long expected=now+oracle.calculate(10,2,haste,slow,isBrave,wind)*1000000L;if((long)CombatAccess.field(actor,"nextActionNanos")!=expected)throw new AssertionError("actual Source spell schedule interval "+timed+"/"+kind);boolean summon=kind.equals("SummonDefinition");if((int)CombatAccess.field(actor,"mp")!=(summon?100:95))throw new AssertionError("original MP debit changed "+kind);if(summon){var counts=(Map<?,?>)CombatAccess.field(actor,"skillUseCounts");if(!Integer.valueOf(1).equals(counts.get(1)))throw new AssertionError("original summon count changed");}else{var ready=(Map<?,?>)CombatAccess.field(actor,"skillReadyNanos");long reuse=kind.equals("GroundDefinition")?expected:now+50000000L;if(!Long.valueOf(reuse).equals(ready.get(1)))throw new AssertionError("original reuse clock changed "+kind);}schedules++;}}
  check(schedules==96,"96 actual detached Quest/Time magic/summon/ground/visual schedules match Source and retain MP/reuse/counts");
  check(normalSchedules(oracle,ordinary,qualified,prior)==96,"96 actual detached movement/attack schedules match Source qualified states or complete original unqualified fallback");
  var memoryActor=SourceNpcTargetFailurePlan.actor(true,889,qualified);var memorySnapshot=SourceNpcFactoryMemoryPlan.snapshot(memoryActor);var restored=SourceNpcFactoryMemoryPlan.construct("BattleTimeAttackEncounter$Monster",memorySnapshot,null);check(NativeSourceNpcFactoryType.stamp(restored)==qualified&&Boolean.TRUE.equals(NativeSourceNpcActionIntervals.brave(restored)),"original memory restore keeps exact immutable brave proof without rereading mutable template");
  var actor=SourceNpcTargetFailurePlan.actor(false,888,qualified);check(NativeSourceNpcActionIntervals.base(0,actor)==960&&NativeSourceNpcActionIntervals.brave(10,actor)==7,"Source NPC default and brave scale use original stage order");set(actor,"nativeSourceNpcFactoryType",prior);check(NativeSourceNpcActionIntervals.base(0,actor)==0&&NativeSourceNpcActionIntervals.brave(10,actor)==10,"unqualified actor retains original native values");check(NativeSourceNpcActionIntervals.class.getDeclaredFields().length==0,"no retained actor/Context/Frame registry or TLS");
  System.out.println("PASS"+cases+" Source NPC action intervals immutable-birth/actual-schedule/contracts plus1200 exact Source intervals and96 spell plus96 normal actual detached schedules; no bound AI/IO/Main/SQL/game qualification");
 }
}
